// cards_sex_coach_qa.js — данные для 10-го модуля игры «Предложи партнеру»:
// топ-100 самых популярных вопросов сексологам и секс-коучам с краткими
// ответами. Формат такой же, как у cards_desires_women.js — без фото, без
// forWhom, с рейтингами (см. renderPhotoCard в core.js).
// level (здесь всегда 10), rank — условный номер по популярности вопроса,
// title — вопрос, text — краткий ответ, womenRating/menRating — насколько
// часто этот вопрос задают женщины и мужчины в среднем (0-10).

const SEX_COACH_QA_CARDS = [
  { level: 10, rank: 1, title: 'Как часто «нормально» заниматься сексом?', text: 'Универсальной частоты не существует: подходящим считается такой ритм, который устраивает обоих партнёров и не вызывает давления или чувства обязанности.', womenRating: 8, menRating: 8 },
  { level: 10, rank: 2, title: 'Нормально ли, что желание у партнёров разное?', text: 'Да, разница в либидо часто встречается в парах. Её обсуждают через честный диалог, поиск компромисса и отказ от давления на партнёра.', womenRating: 8, menRating: 7 },
  { level: 10, rank: 3, title: 'Почему влечение снижается спустя годы отношений?', text: 'На желание могут влиять привычка, стресс, усталость, конфликты и изменения в жизни. Близость можно поддерживать вниманием, новизной и открытым разговором.', womenRating: 8, menRating: 7 },
  { level: 10, rank: 4, title: 'Нормально ли не испытывать оргазм каждый раз?', text: 'Да, оргазм не обязан происходить при каждом контакте. Важнее общее самочувствие, удовольствие и отсутствие давления на себя или партнёра.', womenRating: 9, menRating: 6 },
  { level: 10, rank: 5, title: 'Как рассказать партнёру о своих фантазиях?', text: 'Выберите спокойный момент вне интимной близости и расскажите о фантазии как о варианте для обсуждения, а не как о требовании. Партнёр имеет право отказаться.', womenRating: 8, menRating: 7 },
  { level: 10, rank: 6, title: 'Полезно ли смотреть эротику вместе?', text: 'Это может быть вариантом совместного досуга и поводом обсудить желания, если оба партнёра действительно согласны и не чувствуют давления или сравнения.', womenRating: 6, menRating: 7 },
  { level: 10, rank: 7, title: 'Как естественно повысить либидо?', text: 'На желание могут положительно влиять достаточный сон, физическая активность, снижение стресса, эмоциональная близость и решение медицинских проблем.', womenRating: 8, menRating: 6 },
  { level: 10, rank: 8, title: 'Почему после рождения ребёнка пропадает интерес к близости?', text: 'На желание после родов могут влиять недосып, усталость, гормональные изменения, восстановление организма и новая нагрузка. Если проблема сохраняется, стоит обратиться к врачу или специалисту.', womenRating: 8, menRating: 5 },
  { level: 10, rank: 9, title: 'Нормально ли мастурбировать, находясь в отношениях?', text: 'Да, мастурбация может оставаться частью сексуальности человека и сама по себе не означает недостаток любви или близости в отношениях.', womenRating: 6, menRating: 7 },
  { level: 10, rank: 10, title: 'Что делать при разном либидо у партнёров?', text: 'Обсудите потребности без обвинений, определите комфортные формы близости и ищите решение, которое не требует от одного партнёра постоянно уступать. При затяжных трудностях может помочь терапия пары.', womenRating: 7, menRating: 7 },
  { level: 10, rank: 11, title: 'Сколько в среднем длится половой акт?', text: 'Продолжительность сильно различается у разных пар. Само по себе количество минут не определяет качество секса — важнее комфорт и удовлетворённость обоих.', womenRating: 5, menRating: 7 },
  { level: 10, rank: 12, title: 'Почему не получается достичь оргазма только от проникновения?', text: 'Для многих женщин одного проникновения недостаточно, потому что клитор часто является главным источником сексуальной стимуляции. Дополнительные ласки могут быть естественной частью близости.', womenRating: 9, menRating: 5 },
  { level: 10, rank: 13, title: 'Вредно ли иногда имитировать оргазм?', text: 'Разовый случай не обязательно говорит о серьёзной проблеме, но постоянная имитация мешает партнёру понимать реальные ощущения и потребности. Лучше постепенно переходить к честному разговору.', womenRating: 8, menRating: 5 },
  { level: 10, rank: 14, title: 'Как предложить партнёру попробовать новое, не обидев его?', text: 'Говорите о собственном интересе, например: «Мне было бы интересно попробовать это вместе», и избегайте формулировок, которые звучат как критика нынешней близости.', womenRating: 7, menRating: 7 },
  { level: 10, rank: 15, title: 'Почему секс со временем ощущается рутинным?', text: 'Повторяющийся сценарий и снижение новизны могут создавать ощущение рутины. Помогают разговор о желаниях, смена привычного формата и совместные романтические занятия.', womenRating: 8, menRating: 7 },
  { level: 10, rank: 16, title: 'Правда ли, что стресс влияет на влечение?', text: 'Да, длительный стресс может снижать желание, ухудшать настроение и мешать расслаблению. Важно работать не только с интимной частью, но и с причиной напряжения.', womenRating: 7, menRating: 6 },
  { level: 10, rank: 17, title: 'Насколько важен размер?', text: 'Размер обычно имеет меньшее значение, чем принято считать. На удовольствие сильнее влияют внимание, техника, стимуляция, доверие и способность партнёров говорить о своих ощущениях.', womenRating: 5, menRating: 8 },
  { level: 10, rank: 18, title: 'Как справиться с преждевременной эякуляцией?', text: 'Могут помочь снижение темпа, паузы, техники контроля возбуждения и консультация врача или сексолога. Если проблема повторяется и беспокоит, не стоит заниматься самолечением.', womenRating: 4, menRating: 8 },
  { level: 10, rank: 19, title: 'Что делать при периодических трудностях с эрекцией?', text: 'Разовые трудности могут быть связаны со стрессом, усталостью, алкоголем или тревогой. Если проблема повторяется, сохраняется или появилась внезапно, стоит обратиться к врачу.', womenRating: 4, menRating: 8 },
  { level: 10, rank: 20, title: 'Нормально ли иметь фантазии, отличные от партнёра?', text: 'Да, у партнёров не обязаны совпадать все фантазии. Фантазию можно обсуждать без обязательства воплощать её, а любое действие требует согласия обоих.', womenRating: 7, menRating: 7 },
  { level: 10, rank: 21, title: 'Как часто «нормально» мастурбировать, состоя в паре?', text: 'Универсальной нормы нет. Важно, чтобы мастурбация не причиняла физический или эмоциональный дискомфорт и не мешала жизни, отношениям или желанной близости.', womenRating: 5, menRating: 7 },
  { level: 10, rank: 22, title: 'Может ли недосып снижать желание?', text: 'Да, хронический недосып часто уменьшает энергию, ухудшает настроение и снижает интерес к сексу. Восстановление сна может быть важнее поиска новых стимулов.', womenRating: 7, menRating: 6 },
  { level: 10, rank: 23, title: 'Почему секс иногда причиняет дискомфорт?', text: 'Причинами могут быть недостаточное возбуждение, сухость, напряжение мышц, инфекция, травма или другие медицинские факторы. Боль не нужно терпеть: близость следует остановить и разобраться с причиной.', womenRating: 9, menRating: 4 },
  { level: 10, rank: 24, title: 'Что вызывает сухость и как с этим быть?', text: 'Сухость может быть связана с недостатком возбуждения, стрессом, гормональными изменениями, лекарствами или состоянием здоровья. Помогают дополнительное время и подходящий лубрикант, а при сохранении симптомов нужен врач.', womenRating: 8, menRating: 4 },
  { level: 10, rank: 25, title: 'Безопасно ли использовать секс-игрушки вместе?', text: 'Да, если выбирать подходящие изделия, соблюдать инструкцию и гигиену, использовать лубрикант и заранее обсуждать границы. Для анальных игрушек необходим широкий ограничитель.', womenRating: 7, menRating: 6 },
  { level: 10, rank: 26, title: 'Как предложить партнёру пойти к семейному сексологу?', text: 'Говорите о совместной заботе об отношениях: объясните, что хотите лучше понять трудности и найти решение вместе, а не обвинить партнёра.', womenRating: 6, menRating: 6 },
  { level: 10, rank: 27, title: 'Могут ли лекарства влиять на либидо?', text: 'Да, некоторые препараты могут менять желание, возбуждение или способность к оргазму. Не отменяйте лечение самостоятельно — обсудите заметные изменения с врачом.', womenRating: 6, menRating: 6 },
  { level: 10, rank: 28, title: 'Почему иногда возникает тревога перед близостью?', text: 'Тревогу могут вызывать страх оценки, предыдущий негативный опыт, стресс, боль или ожидание «правильного результата». Помогают разговор, более медленный темп и отсутствие давления.', womenRating: 7, menRating: 7 },
  { level: 10, rank: 29, title: 'Как восстановить близость после ссоры?', text: 'Сначала важно восстановить эмоциональную безопасность: выслушать друг друга, признать чувства и обсудить конфликт. Физическая близость не должна использоваться вместо решения проблемы.', womenRating: 8, menRating: 6 },
  { level: 10, rank: 30, title: 'Нормально ли периодическое снижение либидо у женщин?', text: 'Да, желание может меняться под влиянием цикла, беременности, стресса, усталости, лекарств и жизненных обстоятельств. При длительном или резком снижении стоит обратиться к врачу.', womenRating: 8, menRating: 5 },
  { level: 10, rank: 31, title: 'Как возраст влияет на сексуальную функцию?', text: 'С возрастом могут меняться уровень желания, чувствительность, возбуждение и естественная смазка, но сексуальная жизнь не обязана прекращаться. При неприятных симптомах помогут консультация и лечение причины.', womenRating: 6, menRating: 6 },
  { level: 10, rank: 32, title: 'Как без неловкости обсудить обследование на ИППП?', text: 'Предложите обследоваться обоим как обычную заботу о здоровье, особенно при новых отношениях или изменении статуса. Это не должно звучать как обвинение в неверности.', womenRating: 6, menRating: 6 },
  { level: 10, rank: 33, title: 'Почему желание может снижаться во время беременности?', text: 'На желание во время беременности могут влиять гормональные и физические изменения, самочувствие, тревога и рекомендации врача. У одних желание снижается, у других остаётся прежним или повышается.', womenRating: 7, menRating: 5 },
  { level: 10, rank: 34, title: 'Через сколько после родов можно возвращаться к близости?', text: 'Срок зависит от восстановления, способа родоразрешения, самочувствия и медицинских рекомендаций. Не ориентируйтесь только на календарь: возвращаться к близости стоит после заживления и готовности самой женщины.', womenRating: 7, menRating: 5 },
  { level: 10, rank: 35, title: 'Влияют ли гормональные контрацептивы на либидо?', text: 'У некоторых женщин на фоне гормональной контрацепции меняются желание, настроение или естественная смазка. При заметных изменениях обсудите альтернативы с врачом и не отменяйте препарат самостоятельно.', womenRating: 7, menRating: 4 },
  { level: 10, rank: 36, title: 'Нормально ли иногда думать о постороннем во время близости?', text: 'Случайные мысли во время секса встречаются у многих и сами по себе не означают недостаток влечения к партнёру. Если отвлечение постоянно мешает близости, стоит обратить внимание на стресс и эмоциональное состояние.', womenRating: 6, menRating: 6 },
  { level: 10, rank: 37, title: 'Как понять, нужен ли именно секс-терапевт?', text: 'Профильный специалист может помочь, если трудности связаны с желанием, возбуждением, болью, оргазмом, эрекцией или общением и не решаются обычным разговором.', womenRating: 6, menRating: 5 },
  { level: 10, rank: 38, title: 'Почему эрекция иногда пропадает в процессе?', text: 'Причинами могут быть тревога, стресс, усталость, алкоголь, отвлечение или некоторые заболевания. Эпизод не обязательно означает потерю влечения, но повторяющуюся проблему стоит обсудить с врачом.', womenRating: 5, menRating: 8 },
  { level: 10, rank: 39, title: 'Правда ли, что женщинам нужно больше времени для оргазма?', text: 'У многих женщин возбуждение нарастает дольше, чем у мужчин, но индивидуальные различия очень велики. Это не «медлительность», а повод уделять достаточно времени и подходящей стимуляции.', womenRating: 8, menRating: 6 },
  { level: 10, rank: 40, title: 'Как жить с сильно разным либидо годами?', text: 'Помогают регулярный разговор, гибкий ритм, разные формы близости и отказ от давления. Если конфликт сохраняется, полезна консультация сексолога или терапевта пары.', womenRating: 7, menRating: 7 },
  { level: 10, rank: 41, title: 'Влияет ли просмотр порно на реальную близость?', text: 'Влияние зависит от частоты, содержания и личного контекста. Проблемы могут появиться, если порно формирует нереалистичные ожидания, мешает возбуждению с партнёром или используется вопреки договорённостям пары.', womenRating: 5, menRating: 7 },
  { level: 10, rank: 42, title: 'Стоит ли каждой паре пробовать анальный секс?', text: 'Нет, это необязательная практика. Она возможна только при взаимном желании, подготовке, лубриканте и готовности остановиться, а отказ партнёра не требует объяснений.', womenRating: 6, menRating: 6 },
  { level: 10, rank: 43, title: 'Как безопасно начать изучать БДСМ новичкам?', text: 'Начните с обсуждения ролей, границ и стоп-слова, используйте простые практики без ограничения дыхания и заранее подготовьте способ быстро остановить игру.', womenRating: 6, menRating: 7 },
  { level: 10, rank: 44, title: 'Нормально ли ревновать к прошлому партнёра?', text: 'Лёгкая ревность может возникать у многих, но прошлые отношения не определяют нынешнюю ценность пары. Важно не превращать её в контроль, допросы или запреты.', womenRating: 7, menRating: 6 },
  { level: 10, rank: 45, title: 'Как понять, здорова ли сексуальная жизнь пары?', text: 'Ориентируйтесь на взаимное согласие, безопасность, возможность говорить о желаниях и удовлетворённость обоих, а не на частоту или сравнение с другими.', womenRating: 7, menRating: 6 },
  { level: 10, rank: 46, title: 'Почему говорить о сексе так сложно?', text: 'Мешать могут воспитание, стыд, религиозные установки, страх критики и неудачный прошлый опыт. Помогают короткие разговоры в спокойной обстановке и формулировки от первого лица.', womenRating: 8, menRating: 6 },
  { level: 10, rank: 47, title: 'Влияют ли изменения тела на желание?', text: 'Да, недовольство телом и страх оценки могут снижать раскрепощённость и желание. Поддержка партнёра важна, но устойчивую тревогу о внешности также можно обсудить со специалистом.', womenRating: 8, menRating: 5 },
  { level: 10, rank: 48, title: 'Важно ли количество партнёров в прошлом?', text: 'Само количество прошлых партнёров не определяет верность, совместимость или качество нынешних отношений. Важнее честность, безопасность и согласованные ценности пары.', womenRating: 5, menRating: 5 },
  { level: 10, rank: 49, title: 'Как справиться с тревогой перед близостью?', text: 'Снизьте ожидание обязательного результата, обсудите тревогу с партнёром и двигайтесь в комфортном темпе. При сильной или постоянной тревоге может помочь психолог или сексолог.', womenRating: 7, menRating: 7 },
  { level: 10, rank: 50, title: 'Почему оргазм иногда ощущается по-разному?', text: 'Интенсивность оргазма может меняться из-за усталости, стресса, уровня возбуждения, цикла, лекарств и контекста. Различия сами по себе не означают проблему.', womenRating: 7, menRating: 6 },
  { level: 10, rank: 51, title: 'Как алкоголь влияет на близость?', text: 'Алкоголь может временно снизить тревогу, но избыток ухудшает чувствительность, эрекцию, возбуждение и способность дать осознанное согласие. Для безопасной близости оба партнёра должны оставаться в ясном сознании.', womenRating: 5, menRating: 6 },
  { level: 10, rank: 52, title: 'Существует ли женская эякуляция на самом деле?', text: 'Да, женская эякуляция описана в медицинской литературе, но встречается не у всех и может выглядеть по-разному. Отсутствие этого явления также является нормой.', womenRating: 6, menRating: 5 },
  { level: 10, rank: 53, title: 'Как понять сексуальную совместимость с партнёром?', text: 'Сексуальная совместимость определяется не полным совпадением желаний, а готовностью обсуждать их, уважать границы и со временем находить подходящий обоим формат близости.', womenRating: 7, menRating: 6 },
  { level: 10, rank: 54, title: 'Почему партнёр в последнее время меньше проявляет интерес?', text: 'Причинами могут быть усталость, стресс, проблемы со здоровьем, лекарства, эмоциональные трудности или напряжение в отношениях. Лучше спокойно спросить напрямую, а не делать выводы без разговора.', womenRating: 8, menRating: 6 },
  { level: 10, rank: 55, title: 'Как вернуть страсть в длительных отношениях?', text: 'Помогают осознанное время вдвоём, внимание к желаниям партнёра, новые совместные впечатления и честный разговор о том, чего не хватает. Не стоит ждать, что близость всегда восстановится сама.', womenRating: 8, menRating: 7 },
  { level: 10, rank: 56, title: 'Полезны ли откровенные переписки для пары?', text: 'Да, если оба партнёра считают такой формат комфортным. Переписка может поддерживать эмоциональную связь и предвкушение, но не должна становиться обязанностью.', womenRating: 6, menRating: 7 },
  { level: 10, rank: 57, title: 'Что делать, если партнёр хочет то, что мне не близко?', text: 'Спокойно обозначьте, что именно вам не подходит, и не соглашайтесь через силу. Можно обсудить безопасную альтернативу, но отказ партнёра необходимо уважать без давления и осуждения.', womenRating: 7, menRating: 6 },
  { level: 10, rank: 58, title: 'Нормально ли не хотеть секс каждый день, даже влюблённым?', text: 'Да, ежедневное желание не является обязательным признаком любви или силы чувств. Уровень либидо меняется в зависимости от здоровья, усталости, стресса и жизненных обстоятельств.', womenRating: 7, menRating: 6 },
  { level: 10, rank: 59, title: 'Нужно ли обсуждать согласие внутри постоянных отношений?', text: 'Да, постоянные отношения и брак не отменяют необходимости согласия. Желание может меняться изо дня в день, поэтому важно спрашивать, слушать ответ и уважать отказ.', womenRating: 7, menRating: 6 },
  { level: 10, rank: 60, title: 'Как хроническое заболевание влияет на близость и что делать?', text: 'Заболевание может влиять на желание, чувствительность, энергию, боль или физические возможности. Помогают адаптация сценария, открытый разговор и консультация врача по поводу безопасных вариантов.', womenRating: 5, menRating: 5 },
  { level: 10, rank: 61, title: 'Бывает ли низкое либидо у мужчин?', text: 'Да, низкое желание бывает у мужчин и может быть связано со стрессом, недосыпом, депрессией, лекарствами, гормональными или другими медицинскими причинами.', womenRating: 5, menRating: 6 },
  { level: 10, rank: 62, title: 'Как преодолеть стыд из-за воспитания?', text: 'Помогают постепенное пересмотрение убеждений, спокойное обсуждение желаний с безопасным партнёром и работа с психологом или сексологом, если стыд сильно мешает жизни.', womenRating: 6, menRating: 5 },
  { level: 10, rank: 63, title: 'Почему иногда ощущается эмоциональная отстранённость во время секса?', text: 'Такое состояние может быть связано со стрессом, усталостью, тревогой, конфликтами или незавершёнными переживаниями. Это не всегда означает потерю влечения к партнёру.', womenRating: 6, menRating: 5 },
  { level: 10, rank: 64, title: 'Вредно ли постоянно имитировать удовольствие?', text: 'Постоянная имитация мешает партнёрам понимать реальные ощущения и находить подходящие способы близости. Честный разговор обычно полезнее, чем поддержание неверного представления о том, что работает.', womenRating: 7, menRating: 5 },
  { level: 10, rank: 65, title: 'Как попросить больше прелюдии, не задев партнёра?', text: 'Говорите о своих ощущениях и желаниях без обвинений: «Мне нравится, когда мы не спешим» или «Мне нужно больше времени, чтобы возбудиться».', womenRating: 8, menRating: 5 },
  { level: 10, rank: 66, title: 'Меняется ли сексуальная жизнь навсегда после появления детей?', text: 'После появления детей часто меняются время, частота и условия близости из-за усталости и новых обязанностей. Со временем пары могут выстроить новый комфортный ритм.', womenRating: 7, menRating: 6 },
  { level: 10, rank: 67, title: 'Нормально ли иногда вспоминать бывших партнёров?', text: 'Случайные воспоминания не означают неверность или недостаток влечения к нынешнему партнёру. Важнее то, как человек ведёт себя в настоящих отношениях.', womenRating: 5, menRating: 5 },
  { level: 10, rank: 68, title: 'Как меняется желание в период менопаузы?', text: 'Во время менопаузы на желание могут влиять гормональные изменения, сухость, нарушения сна, приливы и настроение. Помогают подходящая адаптация близости и консультация врача при неприятных симптомах.', womenRating: 6, menRating: 4 },
  { level: 10, rank: 69, title: 'Насколько важен тестостерон для мужского либидо?', text: 'Тестостерон участвует в регуляции мужского желания, но на либидо также влияют сон, стресс, настроение, лекарства и общее здоровье. При заметном снижении интереса нужна медицинская оценка, а не самостоятельный приём гормонов.', womenRating: 4, menRating: 6 },
  { level: 10, rank: 70, title: 'Нормально ли планировать секс заранее, а не ждать спонтанности?', text: 'Да, планирование помогает занятым парам выделить время для близости и снизить влияние усталости или бытовых дел. Запланированная встреча не означает, что секс обязательно должен состояться.', womenRating: 7, menRating: 6 },
  { level: 10, rank: 71, title: 'Как обсудить интерес к немоногамии, если он появился?', text: 'Говорите об этом спокойно и как о собственной мысли, а не как о решении за двоих. Партнёр имеет право отказаться, а согласие должно быть добровольным, информированным и без давления.', womenRating: 4, menRating: 5 },
  { level: 10, rank: 72, title: 'Полезно ли наблюдать за мастурбацией партнёра?', text: 'Это может быть способом узнать, какие прикосновения и темп нравятся партнёру, если оба действительно хотят участвовать и чувствуют себя спокойно.', womenRating: 5, menRating: 7 },
  { level: 10, rank: 73, title: 'Сколько должна длиться прелюдия?', text: 'Универсального времени нет. Прелюдия может длиться столько, сколько нужно обоим партнёрам для возбуждения, расслабления и комфортного перехода к следующему этапу.', womenRating: 7, menRating: 5 },
  { level: 10, rank: 74, title: 'Почему иногда хочется плакать после секса?', text: 'После близости могут проявиться сильные эмоции, усталость или облегчение. Если плач повторяется, сопровождается страхом, болью или тяжёлыми воспоминаниями, стоит поговорить со специалистом.', womenRating: 7, menRating: 4 },
  { level: 10, rank: 75, title: 'Нормально ли чувствовать усталость после близости?', text: 'Да, физическая активность и эмоциональная разрядка могут вызывать усталость или сонливость. Если слабость необычно сильная, длительная или сопровождается другими симптомами, нужна консультация врача.', womenRating: 6, menRating: 6 },
  { level: 10, rank: 76, title: 'Помогают ли определённые позы при конкретных особенностях тела?', text: 'Да, положение тела может менять угол, глубину, давление и доступность стимуляции. Подбирать позу лучше постепенно, ориентируясь на комфорт, ощущения и обратную связь партнёров.', womenRating: 7, menRating: 6 },
  { level: 10, rank: 77, title: 'Как справиться с вагинизмом?', text: 'Вагинизм поддаётся лечению, но попытки преодолеть его силой могут усилить боль и напряжение. Обратитесь к гинекологу, физиотерапевту тазового дна или сексологу для индивидуального плана помощи.', womenRating: 6, menRating: 3 },
  { level: 10, rank: 78, title: 'Стоит ли беспокоиться из-за задержки эякуляции?', text: 'Разовый эпизод обычно не является поводом для тревоги. При регулярной задержке или невозможности эякуляции причины могут быть связаны с лекарствами, стрессом, чувствительностью или здоровьем, поэтому стоит обратиться к врачу.', womenRating: 4, menRating: 6 },
  { level: 10, rank: 79, title: 'Как предложить впервые попробовать игрушку в паре?', text: 'Предложите выбрать игрушку вместе и объясните, что это дополнение к близости, а не замена партнёру. Заранее обсудите границы, гигиену, лубрикант и право остановиться.', womenRating: 7, menRating: 6 },
  { level: 10, rank: 80, title: 'Почему либидо иногда усиливается в определённые дни цикла?', text: 'Гормональные колебания в течение менструального цикла могут влиять на желание, но у разных женщин это происходит по-разному. Изменения сами по себе являются нормальными.', womenRating: 7, menRating: 4 },
  { level: 10, rank: 81, title: 'Что такое «тактильный голод» и бывает ли он?', text: 'Тактильный голод — бытовое описание сильной потребности в физическом контакте, например объятиях и прикосновениях. Он не обязательно связан с сексуальным желанием и может возникать при недостатке нежности.', womenRating: 7, menRating: 5 },
  { level: 10, rank: 82, title: 'Как быть, если у партнёров разные предпочтения в экспериментах?', text: 'Обсудите, что интересно каждому, разделите желания на готовность попробовать, сомнение и отказ, а затем ищите только те варианты, которые добровольно подходят обоим.', womenRating: 6, menRating: 6 },
  { level: 10, rank: 83, title: 'Можно ли восстановить близость после измены?', text: 'Иногда это возможно, но процесс требует времени, честности, прекращения обмана и готовности обоих работать над доверием. Парам нередко помогает специалист, но продолжать отношения никто не обязан.', womenRating: 6, menRating: 5 },
  { level: 10, rank: 84, title: 'Есть ли «правильное» дыхание во время секса?', text: 'Жёсткого правила нет. Спокойное дыхание может помогать расслабиться и замечать ощущения, а задерживать дыхание или намеренно ограничивать его не следует.', womenRating: 5, menRating: 4 },
  { level: 10, rank: 85, title: 'Важен ли выбор смазки?', text: 'Да, состав лубриканта влияет на комфорт, совместимость с презервативом и безопасность игрушек. Для латексных презервативов не подходят масла, а при раздражении средство нужно заменить.', womenRating: 6, menRating: 5 },
  { level: 10, rank: 86, title: 'Как возобновить близость после долгого перерыва в паре?', text: 'Начните с общения, объятий, поцелуев и другой несексуальной нежности. Возвращайтесь к интимности постепенно, без установленного срока и ожидания обязательного результата.', womenRating: 7, menRating: 6 },
  { level: 10, rank: 87, title: 'Насколько важен оральный секс для удовлетворённости?', text: 'Для одних пар оральный секс важен, для других — нет или не подходит вовсе. Его значение определяется личными предпочтениями и не является обязательным условием удовлетворённых отношений.', womenRating: 6, menRating: 6 },
  { level: 10, rank: 88, title: 'Как быть с близостью, если стены тонкие или рядом дети?', text: 'Выбирайте время, когда есть приватность, заранее договоритесь о границах и при необходимости используйте спокойный фон. Если невозможно обеспечить конфиденциальность, лучше отложить близость.', womenRating: 6, menRating: 5 },
  { level: 10, rank: 89, title: 'Правда ли, что спорт улучшает сексуальную жизнь?', text: 'Регулярная физическая активность может улучшать выносливость, настроение, кровообращение и уверенность в теле. Это не гарантирует автоматического повышения либидо, потому что на него влияет множество факторов.', womenRating: 5, menRating: 5 },
  { level: 10, rank: 90, title: 'Нормально ли желать меньше близости с возрастом отношений?', text: 'Да, интенсивность желания может меняться из-за привычки, возраста, стресса, здоровья и обстоятельств жизни. Снижение частоты не обязательно означает ухудшение чувств или качества отношений.', womenRating: 6, menRating: 6 },
  { level: 10, rank: 91, title: 'Почему заканчивается «медовый месяц» отношений и это плохо?', text: 'Начальная новизна со временем обычно снижается, а отношения переходят в более привычную и глубокую фазу. Это не обязательно означает угасание чувств, но близость требует внимания и совместных усилий.', womenRating: 6, menRating: 5 },
  { level: 10, rank: 92, title: 'Как сохранить близость на расстоянии?', text: 'Помогают регулярные разговоры, видеосвязь, откровенная переписка по взаимному желанию и планы встреч. Важно выбрать формат, который комфортен обоим, а не поддерживать связь из чувства долга.', womenRating: 6, menRating: 6 },
  { level: 10, rank: 93, title: 'Угрожает ли вибратор мужской самооценке?', text: 'Сам по себе вибратор не угрожает самооценке: это инструмент для совместного удовольствия и исследования ощущений, а не замена партнёру или оценка его способностей.', womenRating: 5, menRating: 6 },
  { level: 10, rank: 94, title: 'Как справиться с давлением стандартов из порно?', text: 'Помните, что порно является постановочным контентом и не отражает обычную близость, тела или реакции людей. Ориентируйтесь на реальные ощущения, безопасность и согласие вашей пары.', womenRating: 5, menRating: 6 },
  { level: 10, rank: 95, title: 'Помогает ли медитация сексуальной жизни?', text: 'Практики осознанности могут снижать тревожность и помогать замечать ощущения во время близости. Это дополнительный инструмент, а не обязательное или универсальное решение.', womenRating: 5, menRating: 4 },
  { level: 10, rank: 96, title: 'Важна ли забота друг о друге сразу после близости?', text: 'Да, объятия, вода, спокойный разговор или другое внимание после близости помогают партнёрам чувствовать себя в безопасности и эмоциональном контакте.', womenRating: 8, menRating: 5 },
  { level: 10, rank: 97, title: 'Когда затишье в близости — это нормально, а когда сигнал проблемы?', text: 'Краткие периоды снижения активности нормальны при усталости, стрессе или изменениях в жизни. Если затишье длится долго, беспокоит кого-то из партнёров и не обсуждается, это повод спокойно поговорить и при необходимости обратиться за помощью.', womenRating: 7, menRating: 6 },
  { level: 10, rank: 98, title: 'Не поздно ли что-то менять после многих лет рутины?', text: 'Менять формат отношений и близости не поздно. Начните с честного разговора, небольших совместных шагов и реалистичных ожиданий вместо попытки сразу изменить всё.', womenRating: 7, menRating: 6 },
  { level: 10, rank: 99, title: 'Стоит ли делиться сексуальным прошлым с новым партнёром?', text: 'Не обязательно рассказывать все подробности, но важно честно обсудить здоровье, тестирование на ИППП, границы и значимые обстоятельства, влияющие на нынешние отношения.', womenRating: 5, menRating: 5 },
  { level: 10, rank: 100, title: 'Какой самый частый совет дают сексологи парам?', text: 'Регулярно и без обвинений говорить о желаниях, границах, самочувствии и изменениях в близости. Открытый диалог помогает заметить проблему раньше и вместе искать решение.', womenRating: 8, menRating: 7 },
  { level: 10, rank: 101, title: 'Существует ли настоящая G-точка?', text: 'Термин «G-точка» описывает чувствительную область на передней стенке влагалища, но её расположение и ощущения различаются. Не все женщины получают от этой зоны удовольствие, и это нормально.', womenRating: 7, menRating: 5 },
  { level: 10, rank: 102, title: 'Что такое мужская G-точка?', text: 'Под этим неофициальным названием обычно имеют в виду простату — железу, расположенную рядом с прямой кишкой. Её стимуляция может быть приятной для некоторых мужчин, но подходит не всем и возможна только при взаимном согласии.', womenRating: 4, menRating: 6 },
  { level: 10, rank: 103, title: 'Сколько раз подряд может испытать оргазм женщина?', text: 'Некоторые женщины способны испытывать несколько оргазмов за один период возбуждения, а другим нужна пауза или это недоступно. Количество индивидуально и не является показателем нормы или качества близости.', womenRating: 7, menRating: 5 },
  { level: 10, rank: 104, title: 'Почему рефрактерный период у мужчин у всех разный?', text: 'Время восстановления после оргазма зависит от возраста, здоровья, уровня возбуждения, стресса и индивидуальной физиологии. Единой нормы продолжительности не существует.', womenRating: 5, menRating: 6 },
  { level: 10, rank: 105, title: 'Может ли тестостероновая терапия помочь при низком либидо?', text: 'Она может помочь при подтверждённом дефиците тестостерона, но не является универсальным средством от низкого желания. Назначать и контролировать лечение должен врач после обследования.', womenRating: 4, menRating: 6 },
  { level: 10, rank: 106, title: 'Помогает ли вагинальный эстроген при сухости в менопаузе?', text: 'Местный вагинальный эстроген может уменьшать сухость и дискомфорт у некоторых женщин в период менопаузы. Подходящее лечение и противопоказания нужно обсудить с врачом.', womenRating: 6, menRating: 3 },
  { level: 10, rank: 107, title: 'Безопасно ли использовать лубрикант с презервативами?', text: 'Да, но состав имеет значение: масла могут повреждать латекс, а силиконовый лубрикант может повредить некоторые силиконовые игрушки. Проверяйте инструкцию к презервативу, игрушке и смазке.', womenRating: 6, menRating: 6 },
  { level: 10, rank: 108, title: 'Как выбрать безопасный материал для игрушек?', text: 'Ищите изделия из непористых материалов с понятным составом и инструкцией: медицинский силикон, стекло и нержавеющая сталь часто считаются подходящими вариантами. Проверяйте целостность изделия и рекомендации производителя.', womenRating: 6, menRating: 4 },
  { level: 10, rank: 109, title: 'Как правильно ухаживать за секс-игрушками?', text: 'Очищайте игрушку до и после использования способом, указанным производителем, обычно водой и мягким мылом или специальным средством. Полностью высушивайте её и храните отдельно в чистом чехле.', womenRating: 5, menRating: 4 },
  { level: 10, rank: 110, title: 'Как предложить партнёру игрушку, не задев его самооценку?', text: 'Предложите выбрать игрушку вместе и объясните, что она может быть дополнением к близости, а не заменой партнёру. Дайте возможность спокойно отказаться без обиды и давления.', womenRating: 6, menRating: 6 },
  { level: 10, rank: 111, title: 'Нужно ли стоп-слово, если пара не занимается БДСМ?', text: 'Стоп-слово полезно при любых новых или необычных практиках: оно заранее обозначает сигнал немедленной остановки. При этом обычная фраза «стоп» или «мне нужно остановиться» всегда должна работать.', womenRating: 6, menRating: 6 },
  { level: 10, rank: 112, title: 'Обязателен ли афтеркеа только в БДСМ-практиках?', text: 'Нет, забота после близости полезна в любых отношениях. Объятия, вода, разговор, плед или просто уважение к желанию побыть одному помогают восстановить комфорт.', womenRating: 7, menRating: 5 },
  { level: 10, rank: 113, title: 'Как вежливо остановить нежеланный сценарий в процессе?', text: 'Скажите прямо и спокойно: «Я хочу остановиться», «Мне неприятно» или «Давай сменим формат». Объяснение не обязательно, а согласие можно отозвать в любой момент.', womenRating: 7, menRating: 6 },
  { level: 10, rank: 114, title: 'Нужно ли заново обсуждать границы спустя годы отношений?', text: 'Да, предпочтения, состояние здоровья и обстоятельства могут меняться. Периодическая проверка границ помогает убедиться, что прежние договорённости всё ещё подходят обоим.', womenRating: 7, menRating: 6 },
  { level: 10, rank: 115, title: 'Что считается изменой в отношениях помимо физической близости?', text: 'Определение зависит от договорённостей пары. Для одних изменой будет только секс, для других — скрытая переписка, романтическая связь или эмоциональная близость на стороне.', womenRating: 6, menRating: 5 },
  { level: 10, rank: 116, title: 'Что такое эмоциональная измена?', text: 'Это скрытая эмоциональная или романтическая связь с другим человеком, которая нарушает договорённости пары и начинает занимать место доверия и близости в отношениях.', womenRating: 6, menRating: 5 },
  { level: 10, rank: 117, title: 'Где проходит граница безобидного флирта в переписке?', text: 'Граница определяется правилами конкретной пары: важны содержание сообщений, секретность, намерения и реакция партнёра. Лучше договориться об этом заранее, а не проверять границы скрытно.', womenRating: 6, menRating: 5 },
  { level: 10, rank: 118, title: 'Как обсуждать близкую дружбу партнёра с бывшими?', text: 'Говорите о собственных чувствах и конкретных ситуациях, а не обвиняйте партнёра в неверности. Обсудите прозрачность общения, границы и то, что поможет обоим чувствовать себя безопаснее.', womenRating: 5, menRating: 5 },
  { level: 10, rank: 119, title: 'Нормально ли влияние религиозного воспитания на отношение к сексу?', text: 'Да, религиозные и семейные убеждения могут влиять на чувство вины, стыд и представления о допустимой близости. С этим можно постепенно работать самостоятельно или с психологом, который уважает ценности человека.', womenRating: 5, menRating: 4 },
  { level: 10, rank: 120, title: 'Как справиться с чувством вины из-за «культуры чистоты»?', text: 'Начните отделять собственные ценности от усвоенных запретов, изучайте достоверную информацию о согласии и сексуальном здоровье и двигайтесь в комфортном темпе. При сильном стыде может помочь психолог.', womenRating: 5, menRating: 3 },
  { level: 10, rank: 121, title: 'Нормально ли волноваться перед первым разом с новым партнёром?', text: 'Да, тревога перед новым опытом естественна. Открытый разговор о границах, контрацепции, защите от ИППП и постепенный темп помогают снизить напряжение.', womenRating: 5, menRating: 5 },
  { level: 10, rank: 122, title: 'Что считается «потерей девственности»?', text: 'Это не универсальное медицинское понятие: люди по-разному определяют его в зависимости от личных и культурных взглядов. Медицинский осмотр не может достоверно установить «девственность».', womenRating: 4, menRating: 3 },
  { level: 10, rank: 123, title: 'Безопасен ли анальный секс при правильной подготовке?', text: 'Он может быть безопаснее при взаимном согласии, медленном темпе, достаточном количестве лубриканта, презервативе и остановке при боли. Анальная ткань легко травмируется, поэтому спешка и давление недопустимы.', womenRating: 5, menRating: 6 },
  { level: 10, rank: 124, title: 'Почему анальный секс может быть болезненным?', text: 'Причинами могут быть недостаток лубриканта, спешка, напряжение мышц, неподходящий размер или медицинская проблема. Боль — сигнал остановиться, а не продолжать через силу.', womenRating: 5, menRating: 4 },
  { level: 10, rank: 125, title: 'Как подготовиться к анальному сексу заранее?', text: 'Обсудите согласие и стоп-сигнал, подготовьте лубрикант и презерватив, начните медленно и не используйте обезболивающие средства, которые могут скрыть травму. Гигиена должна быть мягкой, без агрессивного очищения.', womenRating: 4, menRating: 5 },
  { level: 10, rank: 126, title: 'Нужны ли латексные салфетки для орального секса?', text: 'Латексные салфетки или разрезанный презерватив могут снизить риск передачи некоторых ИППП при оральном контакте. Это не обязательный атрибут для всех, но полезный вариант барьерной защиты.', womenRating: 4, menRating: 3 },
  { level: 10, rank: 127, title: 'Как быть с вопросами гигиены перед оральным сексом?', text: 'Обычного душа или ополаскивания обычно достаточно. Не нужно использовать агрессивные средства или спринцевание: важнее комфорт, отсутствие симптомов инфекции и открытый разговор.', womenRating: 5, menRating: 5 },
  { level: 10, rank: 128, title: 'Нормально ли не глотать во время орального секса?', text: 'Да, это личный выбор и не показатель любви, доверия или уровня близости. Партнёр не должен давить, а вариант завершения нужно обсудить заранее.', womenRating: 4, menRating: 5 },
  { level: 10, rank: 129, title: 'Безопасен ли секс во время беременности?', text: 'При нормально протекающей беременности секс чаще всего безопасен, но при кровотечении, боли, подтекании вод или врачебных ограничениях нужна консультация. В сомнительной ситуации ориентируйтесь на своего врача.', womenRating: 6, menRating: 4 },
  { level: 10, rank: 130, title: 'Как грудное вскармливание влияет на либидо?', text: 'Гормональные изменения, усталость и сухость могут временно снижать желание во время грудного вскармливания. Помогают отдых, лубрикант, больше времени и обсуждение дискомфорта с врачом.', womenRating: 7, menRating: 3 },
  { level: 10, rank: 131, title: 'Сколько восстанавливаться после кесарева сечения перед близостью?', text: 'Срок зависит от заживления, самочувствия и рекомендаций врача; ориентироваться только на фиксированное количество недель не стоит. Возвращение к близости должно быть постепенным и без боли.', womenRating: 6, menRating: 3 },
  { level: 10, rank: 132, title: 'Как эпизиотомия влияет на последующую близость?', text: 'После эпизиотомии тканям нужно время для заживления, а в первые месяцы возможны чувствительность, сухость или болезненность. При сохраняющемся дискомфорте обратитесь к гинекологу или физиотерапевту тазового дна.', womenRating: 6, menRating: 2 },
  { level: 10, rank: 133, title: 'Помогает ли физиотерапия тазового дна при дискомфорте?', text: 'Специализированная физиотерапия может помогать при боли, слабости или чрезмерном напряжении мышц тазового дна, в том числе после родов или операций. Программу должен подбирать квалифицированный специалист.', womenRating: 6, menRating: 2 },
  { level: 10, rank: 134, title: 'Как лечится вагинизм на практике?', text: 'Лечение может включать работу с врачом или сексологом, постепенные упражнения, физиотерапию тазового дна и снижение тревоги. Болезненное проникновение нельзя преодолевать силой.', womenRating: 6, menRating: 2 },
  { level: 10, rank: 135, title: 'Что вызывает задержку эякуляции?', text: 'Причинами могут быть лекарства, алкоголь, стресс, тревога, особенности стимуляции, заболевания нервной системы и другие факторы. При регулярной проблеме стоит обратиться к врачу, а не менять лечение самостоятельно.', womenRating: 3, menRating: 6 },
  { level: 10, rank: 136, title: 'Какие причины эректильной дисфункции наиболее частые?', text: 'На эрекцию могут влиять стресс, тревога, усталость, алкоголь, побочные эффекты лекарств, сосудистые заболевания, диабет и другие состояния. Повторяющиеся трудности требуют медицинской оценки.', womenRating: 3, menRating: 7 },
  { level: 10, rank: 137, title: 'Безопасны ли препараты для усиления эрекции?', text: 'Препараты могут быть эффективными и безопасными при назначении врача с учётом противопоказаний и взаимодействий. Нельзя сочетать их с нитратами и покупать сомнительные средства без контроля состава.', womenRating: 3, menRating: 6 },
  { level: 10, rank: 138, title: 'Работают ли натуральные добавки для либидо?', text: 'Для большинства добавок убедительные доказательства эффективности ограничены, а состав некоторых продуктов бывает ненадёжным. Перед приёмом лучше обсудить средство с врачом, особенно при хронических заболеваниях.', womenRating: 4, menRating: 5 },
  { level: 10, rank: 139, title: 'До какого возраста сохраняется активная сексуальная жизнь?', text: 'Универсального возраста окончания сексуальной жизни нет. Желание и близость могут сохраняться в пожилом возрасте, хотя здоровье, лекарства и изменения тела иногда требуют адаптации.', womenRating: 4, menRating: 4 },
  { level: 10, rank: 140, title: 'Как начинать новые отношения после потери партнёра в возрасте?', text: 'Единого правильного срока нет: важно учитывать собственную готовность, горе, интерес к новым отношениям и безопасность. Новый роман не отменяет прежнюю любовь и не обязан начинаться по чужим ожиданиям.', womenRating: 3, menRating: 3 },
  { level: 10, rank: 141, title: 'Нужно ли раскрывать диагноз ИППП новому партнёру?', text: 'Да, о диагностированной инфекции нужно сообщить до сексуального контакта, чтобы партнёр мог принять информированное решение и обсудить лечение, защиту и необходимые ограничения с врачом.', womenRating: 5, menRating: 5 },
  { level: 10, rank: 142, title: 'Как часто стоит проходить обследование на ИППП?', text: 'Периодичность зависит от вида сексуальных контактов, числа партнёров, использования защиты и индивидуальных рисков. При симптомах или возможном контакте с инфекцией нужно обратиться к врачу, не дожидаясь планового обследования.', womenRating: 5, menRating: 5 },
  { level: 10, rank: 143, title: 'Что такое «период окна» при тестировании на инфекции?', text: 'Это время после заражения, когда инфекция уже может присутствовать, но тест ещё не способен надёжно её выявить. Срок зависит от инфекции и метода анализа, поэтому врач может назначить повторное тестирование.', womenRating: 4, menRating: 4 },
  { level: 10, rank: 144, title: 'Как внутриматочный контрацептив (ВМС) влияет на ощущения во время секса?', text: 'ВМС — это внутриматочный контрацептив, который также называют внутриматочной спиралью. Его устанавливают в матке для защиты от беременности. У большинства людей он не вызывает заметных изменений ощущений во время секса. Если появились боль, кровотечение, дискомфорт или партнёр чувствует нити, обратитесь к гинекологу.', womenRating: 5, menRating: 3 },
  { level: 10, rank: 145, title: 'Как вазэктомия влияет на ощущения у мужчины?', text: 'Вазэктомия обычно не снижает тестостерон, желание, эрекцию или способность испытывать оргазм, но делает мужчину стерильным не сразу. После процедуры нужны контрольные анализы и временная дополнительная контрацепция.', womenRating: 3, menRating: 5 },
  { level: 10, rank: 146, title: 'Как перевязка труб влияет на либидо женщины?', text: 'Перевязка маточных труб обычно не изменяет уровень половых гормонов напрямую, потому что яичники продолжают работать. На желание могут влиять восстановление, стресс, возраст и другие факторы.', womenRating: 4, menRating: 2 },
  { level: 10, rank: 147, title: 'Сколько нужно времени на восстановление после операции для близости?', text: 'Срок зависит от вида операции, заживления, боли и рекомендаций хирурга. Возвращаться к близости следует постепенно и только после разрешения врача, особенно если операция затрагивала таз или половые органы.', womenRating: 4, menRating: 3 },
  { level: 10, rank: 148, title: 'Может ли химиотерапия или лучевая терапия влиять на либидо?', text: 'Да, лечение рака может временно или длительно влиять на желание, гормоны, чувствительность, эрекцию, естественную смазку и уровень энергии. Обсудите симптомы с онкологом: существуют способы поддержать качество жизни.', womenRating: 4, menRating: 3 },
  { level: 10, rank: 149, title: 'Как хроническая боль влияет на сексуальную жизнь пары?', text: 'Боль может снижать желание, ограничивать движения и усиливать тревогу, но не обязательно исключает близость. Помогают адаптация поз и темпа, обезболивание по назначению врача и честное обсуждение ощущений.', womenRating: 4, menRating: 3 },
  { level: 10, rank: 150, title: 'Как обсуждать особенности близости при инвалидности партнёра?', text: 'Обсуждайте возможности, ограничения, помощь, комфортные положения и способы общения без жалости и предположений. Решения должны учитывать самостоятельность, безопасность и желания самого партнёра.', womenRating: 3, menRating: 3 },
  { level: 10, rank: 151, title: 'Влияют ли антидепрессанты на либидо?', text: 'Некоторые антидепрессанты могут снижать желание, возбуждение или способность к оргазму. Не отменяйте препарат самостоятельно: сообщите врачу о побочных эффектах, чтобы обсудить корректировку лечения или альтернативы.', womenRating: 6, menRating: 5 },
  { level: 10, rank: 152, title: 'Можно ли скорректировать сексуальные побочные эффекты лекарств?', text: 'Иногда врач может изменить дозировку, время приёма, препарат или подобрать дополнительное лечение. Не прекращайте приём самостоятельно: обсудите изменения желания, возбуждения или оргазма с назначившим врачом.', womenRating: 5, menRating: 5 },
  { level: 10, rank: 153, title: 'Как тревожное расстройство влияет на близость?', text: 'Постоянная тревога может мешать расслабиться, снижать желание и затруднять возбуждение или оргазм. Лечение тревожного расстройства и спокойный разговор с партнёром часто улучшают и интимную сферу.', womenRating: 6, menRating: 5 },
  { level: 10, rank: 154, title: 'Как депрессия связана со снижением либидо?', text: 'Снижение желания часто сопровождает депрессию вместе с усталостью, подавленным настроением и потерей интереса к привычным занятиям. Это симптом состояния, а не личная вина и не обязательно признак проблем в отношениях.', womenRating: 6, menRating: 5 },
  { level: 10, rank: 155, title: 'Может ли психотерапия помочь и в интимной сфере?', text: 'Да, психотерапия может помочь при тревоге, низкой самооценке, последствиях травмы, конфликтах и трудностях общения, которые влияют на близость. При медицинских симптомах она дополняет, но не заменяет консультацию врача.', womenRating: 6, menRating: 4 },
  { level: 10, rank: 156, title: 'Чем секс-терапевт отличается от обычного психолога?', text: 'Секс-терапевт дополнительно специализируется на сексуальном желании, возбуждении, боли, оргазме, эрекции, границах и интимном общении. Он может работать индивидуально или с парой в зависимости от задачи.', womenRating: 5, menRating: 4 },
  { level: 10, rank: 157, title: 'Стоит ли идти к терапевту вдвоём или по отдельности?', text: 'Формат зависит от проблемы: иногда полезна совместная работа, иногда сначала нужны индивидуальные встречи. Специалист обычно помогает определить подходящий вариант после первичной консультации.', womenRating: 5, menRating: 4 },
  { level: 10, rank: 158, title: 'Как понять, что пора обратиться за помощью, а не ждать?', text: 'Обратитесь к специалисту, если трудности длятся месяцами, вызывают боль, тревогу, дистанцию или конфликты и не меняются после спокойных разговоров. При внезапных физических симптомах лучше начать с врача.', womenRating: 6, menRating: 5 },
  { level: 10, rank: 159, title: 'Можно ли восстановить доверие после эмоциональной измены?', text: 'Иногда доверие удаётся восстановить, но процесс требует прекращения скрытой связи, честности, времени и готовности обоих партнёров работать над отношениями. Парам может помочь семейный терапевт.', womenRating: 5, menRating: 4 },
  { level: 10, rank: 160, title: 'Как справиться с ревностью к соцсетям партнёра?', text: 'Обсудите конкретные действия, которые вызывают тревогу, и договоритесь о границах онлайн-общения без тотального контроля и тайной проверки телефона.', womenRating: 6, menRating: 5 },
  { level: 10, rank: 161, title: 'Влияет ли просмотр эротического контента на отношения?', text: 'Влияние зависит от частоты, содержания и договорённостей пары. Проблема возникает, если контент вызывает скрытность, конфликты, нереалистичные ожидания или вытесняет желанную близость.', womenRating: 4, menRating: 5 },
  { level: 10, rank: 162, title: 'Как понять, что потребление контента стало проблемой?', text: 'Обратите внимание, если просмотр трудно контролировать, он мешает работе, сну или отношениям, заменяет реальную близость или сопровождается постоянной скрытностью и конфликтами.', womenRating: 4, menRating: 4 },
  { level: 10, rank: 163, title: 'Нормально ли партнёрам иметь разный уровень интереса к экспериментам?', text: 'Да, интересы могут различаться. Важно находить добровольно общее пространство желаний и уважать отказ или неготовность партнёра без уговоров и давления.', womenRating: 6, menRating: 5 },
  { level: 10, rank: 164, title: 'Как обсудить желание попробовать лёгкий БДСМ без давления?', text: 'Начните с разговора вне спальни и конкретно объясните, какие элементы вам интересны. Дайте партнёру время подумать, обсудите границы и не ожидайте немедленного согласия.', womenRating: 5, menRating: 5 },
  { level: 10, rank: 165, title: 'Опасны ли лёгкие практики удушения?', text: 'Да, давление на шею может привести к потере сознания, повреждению сосудов, нервов или дыхательных путей даже без заметных следов. Самый безопасный вариант — не использовать практики с ограничением дыхания.', womenRating: 3, menRating: 3 },
  { level: 10, rank: 166, title: 'Как безопасно использовать фиксацию рук или ног?', text: 'Используйте мягкие специальные аксессуары, не затягивайте их, не фиксируйте шею и держите средство быстрого освобождения рядом. Заранее договоритесь о стоп-слове и регулярно проверяйте чувствительность и кровообращение.', womenRating: 5, menRating: 5 },
  { level: 10, rank: 167, title: 'Что важно знать перед первым опытом ролевых игр?', text: 'Заранее обсудите сценарий, роли, допустимые слова и действия, стоп-слово и порядок завершения. Начинайте с простого варианта и помните, что любой партнёр может остановить игру без объяснений.', womenRating: 6, menRating: 5 },
  { level: 10, rank: 168, title: 'Как выйти из роли после интенсивной ролевой игры?', text: 'Завершите сценарий ясной фразой, снимите костюмы и реквизит, поговорите и предложите объятия или другое комфортное проявление заботы. После игры полезно обсудить, что понравилось и что стоит изменить.', womenRating: 6, menRating: 4 },
  { level: 10, rank: 169, title: 'Нормально ли иметь фантазии, которые не хочется воплощать?', text: 'Да, фантазия и реальное желание не обязаны совпадать. Можно обсуждать её как мысль или образ, не соглашаясь на воплощение.', womenRating: 6, menRating: 5 },
  { level: 10, rank: 170, title: 'Как понять разницу между любопытством и настоящим желанием?', text: 'Обсудите, что именно привлекает и какие условия нужны для комфорта. Небольшие безопасные шаги помогают понять ощущения, но отсутствие желания продолжать нужно уважать.', womenRating: 5, menRating: 5 },
  { level: 10, rank: 171, title: 'Может ли пара иметь здоровую сексуальную жизнь без разнообразия поз?', text: 'Да, разнообразие не является обязательным условием. Здоровая интимная жизнь строится на согласии, безопасности, комфорте и удовлетворённости обоих.', womenRating: 5, menRating: 5 },
  { level: 10, rank: 172, title: 'Стоит ли пробовать новые позы просто ради разнообразия?', text: 'Только если интерес есть у обоих. Эксперимент не должен причинять боль, создавать давление или превращаться в обязанность ради самого факта новизны.', womenRating: 5, menRating: 6 },
  { level: 10, rank: 173, title: 'Как выбрать позу для конкретного дискомфорта, например боли в спине?', text: 'Выбирайте положение с меньшей нагрузкой на болезненную область, используйте подушки и контролируйте темп. При повторяющейся или сильной боли сначала обратитесь к врачу.', womenRating: 5, menRating: 4 },
  { level: 10, rank: 174, title: 'Помогают ли определённые позы при разнице в росте партнёров?', text: 'Да, часто помогают положения лёжа, использование устойчивой опоры, подушек и регулировка высоты поверхности. Выбирайте вариант, в котором обоим удобно сохранять равновесие.', womenRating: 4, menRating: 4 },
  { level: 10, rank: 175, title: 'Как деликатно предложить партнёру сменить позу во время близости?', text: 'Скажите коротко и доброжелательно: «Давай попробуем по-другому» или «Мне будет удобнее, если мы сменим положение». Молчаливое терпение не помогает партнёру понять ваши ощущения.', womenRating: 6, menRating: 5 },
  { level: 10, rank: 176, title: 'Нормально ли партнёрам иметь разные любимые позы?', text: 'Да, это обычная ситуация. Партнёры могут чередовать предпочтительные позы, выбирать компромиссный вариант или уделять каждому время в подходящем формате.', womenRating: 5, menRating: 5 },
  { level: 10, rank: 177, title: 'Как справиться с судорогой или неудобством во время секса?', text: 'Остановитесь, аккуратно измените положение, расслабьте мышцу и сделайте паузу. Не нужно смущаться или продолжать через боль; при частых судорогах обсудите их с врачом.', womenRating: 5, menRating: 4 },
  { level: 10, rank: 178, title: 'Что делать, если во время близости стало не смешно, а неловко?', text: 'Остановитесь или замедлитесь, назовите неловкость и спокойно обсудите её. Смех может помочь, но не обязанность: важнее, чтобы оба снова почувствовали себя безопасно.', womenRating: 6, menRating: 6 },
  { level: 10, rank: 179, title: 'Нормально ли иногда терять возбуждение в процессе?', text: 'Да, возбуждение может меняться из-за усталости, тревоги, отвлечения, боли или смены темпа. Сделайте паузу, поговорите и продолжайте только при желании обоих.', womenRating: 6, menRating: 6 },
  { level: 10, rank: 180, title: 'Как быть, если один партнёр закончил раньше другого?', text: 'Близость не обязана заканчиваться с первым оргазмом: можно продолжить поцелуями, прикосновениями или другими комфортными ласками. При этом партнёр после оргазма имеет право остановиться.', womenRating: 6, menRating: 5 },
  { level: 10, rank: 181, title: 'Насколько нормально не хотеть секс сразу после конфликта?', text: 'Это нормально: многим нужно время, чтобы успокоиться и снова почувствовать эмоциональную безопасность. Не используйте близость как обязанность или способ заставить партнёра забыть конфликт.', womenRating: 6, menRating: 5 },
  { level: 10, rank: 182, title: 'Можно ли использовать близость, чтобы избежать серьёзного разговора?', text: 'Близость может временно снизить напряжение, но не заменяет обсуждение проблемы. Если нерешённые темы постоянно откладываются, они могут усилить дистанцию и обиду.', womenRating: 5, menRating: 5 },
  { level: 10, rank: 183, title: 'Как понять, что пара вышла из «медового месяца» здорово?', text: 'Обычно это видно по переходу от постоянной новизны к спокойной близости, в которой сохраняются тепло, уважение, интерес и возможность говорить о сложностях.', womenRating: 6, menRating: 5 },
  { level: 10, rank: 184, title: 'Нормально ли меньше хотеть близости после многих лет вместе?', text: 'Да, желание может меняться из-за привычки, возраста, стресса, здоровья и жизненных обстоятельств. Снижение частоты не обязательно означает потерю любви или привязанности.', womenRating: 6, menRating: 6 },
  { level: 10, rank: 185, title: 'Как поддерживать интерес друг к другу спустя десятилетия?', text: 'Помогают внимание к партнёру, совместные впечатления, личное пространство, забота о здоровье и регулярный разговор о том, что сейчас приятно и важно каждому.', womenRating: 7, menRating: 6 },
  { level: 10, rank: 186, title: 'Может ли смена места жительства повлиять на близость пары?', text: 'Да, переезд часто связан со стрессом, усталостью, финансовыми расходами и нарушением привычного ритма. Желание может восстановиться после адаптации и появления чувства стабильности.', womenRating: 5, menRating: 4 },
  { level: 10, rank: 187, title: 'Как финансовые трудности отражаются на сексуальной жизни?', text: 'Денежный стресс может ухудшать сон, настроение, чувство безопасности и желание. Помогают открытое обсуждение нагрузки, совместное планирование и поддержка, а не обвинения.', womenRating: 5, menRating: 5 },
  { level: 10, rank: 188, title: 'Может ли потеря работы повлиять на либидо?', text: 'Да, потеря работы может снижать самооценку, усиливать тревогу и отнимать энергию, поэтому желание иногда временно уменьшается. Поддержка партнёра и работа со стрессом могут облегчить состояние.', womenRating: 4, menRating: 5 },
  { level: 10, rank: 189, title: 'Как горе или утрата влияют на сексуальную жизнь пары?', text: 'Горе может временно или надолго менять желание, способность расслабляться и потребность в прикосновениях. Партнёрам важно дать друг другу время и не требовать быстрого возвращения к прежнему ритму.', womenRating: 5, menRating: 4 },
  { level: 10, rank: 190, title: 'Как справиться с трудностями при попытках зачать ребёнка?', text: 'Секс по расписанию и давление ожиданий могут снижать удовольствие и желание. Важно сохранять близость без цели зачатия и при необходимости обратиться к репродуктологу или психологу.', womenRating: 5, menRating: 4 },
  { level: 10, rank: 191, title: 'Как пережить выкидыш и вернуться к близости?', text: 'После выкидыша паре может понадобиться время для физического и эмоционального восстановления. Возвращайтесь к близости только при готовности обоих и после медицинских рекомендаций.', womenRating: 4, menRating: 2 },
  { level: 10, rank: 192, title: 'Как смешанная семья влияет на интимную жизнь пары?', text: 'Дети из предыдущих отношений, разные графики и меньшая приватность могут усложнять близость. Помогают заранее планировать время только для пары и уважать потребность каждого в личном пространстве.', womenRating: 4, menRating: 4 },
  { level: 10, rank: 193, title: 'Как справиться с разным сексуальным опытом партнёров?', text: 'Разный опыт не определяет совместимость. Обсуждайте ожидания, двигайтесь постепенно и относитесь к отношениям как к совместному обучению, а не к проверке навыков.', womenRating: 4, menRating: 4 },
  { level: 10, rank: 194, title: 'Нормально ли партнёрам с разным культурным фоном иметь разные ожидания?', text: 'Да, культура может влиять на представления о ролях, открытости, частоте секса и допустимых практиках. Важно переводить ожидания в конкретные договорённости и искать общий комфорт.', womenRating: 4, menRating: 4 },
  { level: 10, rank: 195, title: 'Как быть, если семья или родственники осуждают открытость пары?', text: 'Интимная жизнь пары относится к частной сфере, и родственники не обязаны знать её детали. Установите спокойные границы и не позволяйте чужому мнению определять ваши добровольные решения.', womenRating: 4, menRating: 4 },
  { level: 10, rank: 196, title: 'Можно ли сохранить страсть при плотном рабочем графике?', text: 'Да, но иногда близость приходится планировать так же, как другие важные дела. Помогают короткие проявления внимания в течение дня и регулярное время без телефонов и рабочих задач.', womenRating: 6, menRating: 6 },
  { level: 10, rank: 197, title: 'Как быть парам с разными часовыми поясами или сменной работой?', text: 'Синхронизация календарей, гибкость и заранее выбранные окна для общения помогают сохранять контакт. Важно учитывать не только время, но и уровень усталости каждого партнёра.', womenRating: 4, menRating: 4 },
  { level: 10, rank: 198, title: 'Помогают ли совместные ритуалы перед сном сближению?', text: 'Да, регулярные объятия, разговор без телефонов, благодарность или совместное чтение могут поддерживать эмоциональную связь даже без секса.', womenRating: 7, menRating: 5 },
  { level: 10, rank: 199, title: 'Как быстро восстановить близость после долгого расставания?', text: 'Не обязательно быстро возвращаться к прежнему темпу. Начните с разговора, объятий и других форм нежности, а затем двигайтесь дальше только при взаимной готовности.', womenRating: 5, menRating: 5 },
  { level: 10, rank: 200, title: 'Может ли пара «переучиться» плохим сексуальным привычкам?', text: 'Да, привычные сценарии можно менять постепенно: замечать, что не работает, обсуждать это и пробовать новые действия с обратной связью и без давления.', womenRating: 5, menRating: 5 },
  { level: 10, rank: 201, title: 'Как узнать, что партнёр действительно удовлетворён?', text: 'Надёжнее всего спросить прямо и спокойно, что партнёру понравилось, чего хотелось бы больше и что можно изменить. Наблюдение за реакциями важно, но не заменяет честного разговора.', womenRating: 7, menRating: 6 },
  { level: 10, rank: 202, title: 'Нормально ли иногда предпочитать просто обняться, а не заниматься сексом?', text: 'Да, потребность в объятиях, прикосновениях и эмоциональной поддержке без сексуальной близости является нормальной частью отношений. Нежность не обязана заканчиваться сексом.', womenRating: 8, menRating: 5 },
  { level: 10, rank: 203, title: 'Как быть, если у партнёров разные представления о романтике?', text: 'Обсудите, какие действия каждый считает проявлением заботы: разговор, подарки, помощь, совместное время или прикосновения. Затем ищите способы, которые понятны и приятны обоим.', womenRating: 6, menRating: 5 },
  { level: 10, rank: 204, title: 'Можно ли научиться дольше сохранять эрекцию?', text: 'Иногда помогают снижение тревоги, паузы, более медленный темп и изменение фокуса внимания. При регулярных трудностях стоит обратиться к врачу, чтобы исключить медицинские причины.', womenRating: 3, menRating: 7 },
  { level: 10, rank: 205, title: 'Как научиться лучше контролировать момент оргазма?', text: 'Могут помочь техники паузы, снижение темпа и отслеживание уровня возбуждения до наступления точки невозврата. Если трудность сохраняется и беспокоит, обсудите её с врачом или сексологом.', womenRating: 3, menRating: 7 },
  { level: 10, rank: 206, title: 'Правда ли, что упражнения Кегеля полезны и мужчинам?', text: 'Упражнения для мышц тазового дна могут помогать некоторым мужчинам контролировать мочеиспускание, эякуляцию и ощущения. Важно правильно выполнять их и не перенапрягать мышцы.', womenRating: 4, menRating: 6 },
  { level: 10, rank: 207, title: 'Как связаны осанка и качество близости?', text: 'Осанка, подвижность и физическая форма могут влиять на комфорт, выносливость и выбор положений. Они не определяют качество близости сами по себе, но иногда помогают уменьшить нагрузку и дискомфорт.', womenRating: 4, menRating: 5 },
  { level: 10, rank: 208, title: 'Может ли йога улучшить сексуальную жизнь?', text: 'Йога может помогать гибкости, осознанности, расслаблению и снижению стресса. Это косвенно поддерживает близость, но не является гарантированным лечением сексуальных трудностей.', womenRating: 5, menRating: 4 },
  { level: 10, rank: 209, title: 'Как недостаток железа или витаминов влияет на либидо?', text: 'Дефицит железа и некоторых питательных веществ может снижать энергию, настроение и общее самочувствие, что косвенно влияет на желание. Добавки стоит принимать только после подтверждения дефицита и рекомендации врача.', womenRating: 4, menRating: 4 },
  { level: 10, rank: 210, title: 'Помогает ли отказ от алкоголя улучшить сексуальную жизнь?', text: 'Уменьшение или отказ от алкоголя может улучшить сон, настроение, чувствительность и сексуальную функцию, особенно если употребление было регулярным или чрезмерным.', womenRating: 4, menRating: 5 },
  { level: 10, rank: 211, title: 'Как курение влияет на эректильную функцию?', text: 'Курение повреждает сосуды и ухудшает кровоток, поэтому связано с повышенным риском эректильных трудностей. Отказ от курения улучшает здоровье сосудов, хотя восстановление может занять время.', womenRating: 3, menRating: 6 },
  { level: 10, rank: 212, title: 'Можно ли восстановить желание после долгого стресса на работе?', text: 'Да, желание часто возвращается после снижения нагрузки, нормализации сна и восстановления времени на отдых. Если стресс сохраняется или сопровождается депрессией, нужна поддержка специалиста.', womenRating: 5, menRating: 5 },
  { level: 10, rank: 213, title: 'Как быть, если один партнёр много путешествует по работе?', text: 'Заранее договоритесь о комфортном формате связи: сообщения, звонки, видеосвязь и время без гаджетов при встречах. Важно учитывать усталость и не превращать общение в обязательный отчёт.', womenRating: 4, menRating: 4 },
  { level: 10, rank: 214, title: 'Реально ли поддерживать страсть на расстоянии долгое время?', text: 'Да, этому помогают регулярное общение, эмоциональная открытость, совместные планы и договорённости о границах. Важно сохранять не только сексуальный, но и обычный человеческий контакт.', womenRating: 5, menRating: 5 },
  { level: 10, rank: 215, title: 'Нормально ли скучать по физической близости больше, чем ожидалось?', text: 'Да, потребность в объятиях, прикосновениях и сексуальном контакте у разных людей выражена по-разному. Это не делает человека зависимым или слабым.', womenRating: 5, menRating: 5 },
  { level: 10, rank: 216, title: 'Как справляться с искушением при долгой разлуке?', text: 'Заранее обсудите границы отношений, допустимые формы общения с другими людьми и ожидания во время разлуки. Честность снижает риск скрытности и конфликтов после встречи.', womenRating: 4, menRating: 4 },
  { level: 10, rank: 217, title: 'Стоит ли обсуждать сексуальные фантазии с психологом?', text: 'Да, специалист поможет отделить фантазию от реального желания, разобраться со стыдом или тревогой и оценить безопасные способы обсуждения или воплощения.', womenRating: 4, menRating: 4 },
  { level: 10, rank: 218, title: 'Как справиться со страхом показаться «странным» из-за фантазий?', text: 'Фантазии сильно различаются и не равны намерениям или действиям. Обсуждать их стоит только с человеком, которому доверяете, без обязанности воплощать то, что не подходит.', womenRating: 5, menRating: 5 },
  { level: 10, rank: 219, title: 'Может ли пара иметь общий «список желаний» на будущее?', text: 'Да, список помогает сохранять идеи и обсуждать их без давления сроков. Полезно разделять пункты на «хотим», «возможно позже» и «не подходит».', womenRating: 6, menRating: 5 },
  { level: 10, rank: 220, title: 'Как реагировать, если партнёр отказывается от вашей идеи?', text: 'Спокойно принять отказ и не воспринимать его как личное оскорбление. Желание одного партнёра не создаёт обязанности для другого, а альтернативу можно обсуждать только без давления.', womenRating: 7, menRating: 6 },
  { level: 10, rank: 221, title: 'Нужно ли пробовать всё хотя бы раз?', text: 'Нет, право не пробовать практику так же важно, как право проявить любопытство. Согласие должно быть добровольным, а отказ не требует убеждения или оправдания.', womenRating: 6, menRating: 5 },
  { level: 10, rank: 222, title: 'Как отличить временный спад желания от серьёзной проблемы?', text: 'Учитывайте длительность, самочувствие и влияние на отношения. Краткий спад часто связан с усталостью или стрессом, а затяжной спад с болью, тревогой или конфликтами требует разговора и, возможно, помощи специалиста.', womenRating: 6, menRating: 5 },
  { level: 10, rank: 223, title: 'Может ли психологическая травма влиять на близость спустя годы?', text: 'Да, травматический опыт может проявляться через тревогу, избегание, боль, трудности с доверием или ощущение потери контроля. Травма-фокусированная терапия может помочь восстановить чувство безопасности.', womenRating: 5, menRating: 4 },
  { level: 10, rank: 224, title: 'Как поддержать партнёра с болезненным прошлым опытом?', text: 'Слушайте без расспросов через силу, не давите на близость и уважайте право остановиться. Полезно спросить, какая поддержка нужна сейчас, и предложить помощь специалиста без принуждения.', womenRating: 6, menRating: 5 },
  { level: 10, rank: 225, title: 'Нормально ли отказаться от определённых практик из-за прошлого опыта?', text: 'Да, пережитый опыт может формировать устойчивые границы, и они заслуживают безусловного уважения. Партнёр не обязан объяснять или пересматривать отказ.', womenRating: 6, menRating: 5 },
  { level: 10, rank: 226, title: 'Как обсуждать сексуальность с партнёром другой сексуальной ориентации в прошлом?', text: 'Говорите с уважением и без попыток переубедить или обесценить прошлый опыт партнёра. Обсуждайте только то, что важно для нынешних границ, доверия и безопасности.', womenRating: 4, menRating: 4 },
  { level: 10, rank: 227, title: 'Как быть, если один партнёр открыл в себе новые интересы со временем?', text: 'Спокойно обсудите, что именно изменилось и какие варианты готовы рассмотреть оба. Новое желание не обязывает партнёра соглашаться, а отказ не требует наказания или давления.', womenRating: 4, menRating: 4 },
  { level: 10, rank: 228, title: 'Можно ли пережить кризис среднего возраста без вреда для пары?', text: 'Да, если не замалчивать изменения в самоощущении, желаниях и приоритетах. Открытый разговор, индивидуальная поддержка и семейная терапия могут помочь пройти период без разрушительных решений.', womenRating: 4, menRating: 4 },
  { level: 10, rank: 229, title: 'Как отношения меняются, когда дети покидают дом?', text: 'У пары появляется больше времени и приватности, но одновременно могут проявиться накопленные дистанция или нерешённые вопросы. Этот этап можно использовать для восстановления общих интересов и близости.', womenRating: 5, menRating: 5 },
  { level: 10, rank: 230, title: 'Как заново узнать партнёра после многих лет вместе?', text: 'Задавайте новые вопросы, пробуйте совместные занятия, обсуждайте изменившиеся ценности и интересы. Долгие отношения не означают, что люди перестают меняться.', womenRating: 6, menRating: 5 },
  { level: 10, rank: 231, title: 'Может ли пара стать ближе именно благодаря трудному периоду?', text: 'Да, совместное преодоление трудностей иногда укрепляет доверие, если партнёры поддерживают друг друга и не используют кризис для обвинений или контроля.', womenRating: 6, menRating: 5 },
  { level: 10, rank: 232, title: 'Как понять, что близость снова стала приоритетом обоих?', text: 'Оба партнёра сами находят время для общения и нежности, интересуются самочувствием друг друга и не воспринимают близость как обязанность или одностороннюю уступку.', womenRating: 6, menRating: 5 },
  { level: 10, rank: 233, title: 'Можно ли слишком много говорить о сексе и это навредит?', text: 'Сам по себе разговор не вреден, если он уважительный и не превращается в давление или постоянный контроль. Важно давать партнёру право на паузу и возвращаться к теме позже.', womenRating: 5, menRating: 5 },
  { level: 10, rank: 234, title: 'Как быть, если партнёр не любит обсуждать эту тему вообще?', text: 'Начинайте с одного небольшого вопроса в спокойное время и объясните, зачем вам разговор. Если партнёр не готов сейчас, договоритесь вернуться к теме позже, а не устраивайте допрос.', womenRating: 5, menRating: 5 },
  { level: 10, rank: 235, title: 'Что делать, если чувствуется, что партнёр стесняется говорить о желаниях?', text: 'Создайте атмосферу без насмешек и оценок, расскажите сначала о собственных чувствах и задавайте открытые вопросы. Молчание или отказ отвечать тоже нужно уважать.', womenRating: 6, menRating: 5 },
  { level: 10, rank: 236, title: 'Может ли юмор навредить разговору о сексе?', text: 'Уместный юмор может снизить напряжение, но шутки над телом, желаниями или отказом ранят и мешают доверию. Если тема серьёзная, не используйте юмор для ухода от разговора.', womenRating: 5, menRating: 5 },
  { level: 10, rank: 237, title: 'Как обсуждать тему без превращения её в конфликт?', text: 'Используйте «я-высказывания», говорите о конкретных ситуациях и своих ощущениях, а не о характере партнёра. Слушайте ответ и делайте паузу, если разговор становится слишком напряжённым.', womenRating: 6, menRating: 5 },
  { level: 10, rank: 238, title: 'Насколько важна честность о симуляции удовольствия для отношений?', text: 'Она важна, потому что постоянная имитация создаёт у партнёра неверное представление о том, что приносит удовольствие. Разговор лучше вести без обвинений и с фокусом на том, что можно изменить сейчас.', womenRating: 6, menRating: 4 },
  { level: 10, rank: 239, title: 'Как признаться партнёру, что раньше имитировали оргазм?', text: 'Выберите спокойный момент и объясните, что имитация была связана со страхом, неловкостью или желанием не расстроить партнёра. Затем расскажите, что помогает вам сейчас, без обвинений в адрес другого.', womenRating: 6, menRating: 4 },
  { level: 10, rank: 240, title: 'Помогает ли ведение совместного дневника близости?', text: 'Некоторым парам дневник помогает замечать связь между сном, стрессом, настроением и желанием. Он должен быть добровольным и не превращаться в отчёт или оценку партнёра.', womenRating: 4, menRating: 3 },
  { level: 10, rank: 241, title: 'Как понять, соответствует ли частота близости среднему уровню пар?', text: 'Средние значения не определяют, что «правильно» именно для вас. Ориентируйтесь на взаимную удовлетворённость, отсутствие давления и возможность спокойно обсуждать изменения.', womenRating: 5, menRating: 5 },
  { level: 10, rank: 242, title: 'Может ли слишком частая близость быть проблемой?', text: 'Частота сама по себе не является проблемой, если обоим комфортно. Стоит обсудить баланс, если близость вызывает боль, усталость, чувство обязанности, конфликты или мешает повседневной жизни.', womenRating: 4, menRating: 4 },
  { level: 10, rank: 243, title: 'Как быть, если желание партнёров совпадает не в одно и то же время дня?', text: 'Обсудите, какое время обычно удобнее каждому, и ищите компромисс без обязанности всегда подстраиваться одному. Иногда помогают планирование и разные формы нежности без секса.', womenRating: 5, menRating: 5 },
  { level: 10, rank: 244, title: 'Нормально ли обсуждать секс с друзьями?', text: 'Общие разговоры о сексуальности нормальны, но личные детали партнёра нельзя раскрывать без его согласия. Уважайте приватность, особенно если информация может его идентифицировать или смутить.', womenRating: 4, menRating: 4 },
  { level: 10, rank: 245, title: 'Как быть, если советы друзей противоречат вашему опыту?', text: 'Советы друзей не заменяют индивидуальный опыт или медицинскую консультацию. Ориентируйтесь на безопасность, комфорт и договорённости вашей пары, а при симптомах обращайтесь к специалисту.', womenRating: 4, menRating: 4 },
  { level: 10, rank: 246, title: 'Может ли пара «перерасти» свои прежние сексуальные привычки?', text: 'Да, предпочтения и обстоятельства могут меняться. Партнёрам полезно периодически проверять, что по-прежнему нравится, а что уже стало неудобным или неинтересным.', womenRating: 5, menRating: 5 },
  { level: 10, rank: 247, title: 'Как понять, что пора обновить «сценарий» близости?', text: 'Повторяющаяся скука, отсутствие интереса или ощущение обязанности могут быть поводом поговорить о переменах. Новизна должна быть добровольной и не обязательно связана с более откровенными практиками.', womenRating: 6, menRating: 5 },
  { level: 10, rank: 248, title: 'Стоит ли бояться перемен в сексуальной жизни с возрастом?', text: 'Перемены в желании, чувствительности и физических возможностях естественны. Их можно обсуждать, адаптировать близость и обращаться к врачу при боли или стойких нарушениях.', womenRating: 5, menRating: 5 },
  { level: 10, rank: 249, title: 'Что важнее — техника или эмоциональная связь?', text: 'Оба фактора могут иметь значение, но эмоциональная безопасность, доверие и возможность говорить о желаниях создают основу для подходящей именно этой паре техники.', womenRating: 8, menRating: 6 },
  { level: 10, rank: 250, title: 'Какой главный вывод стоит помнить о сексуальной жизни пары?', text: 'У каждой пары свой комфортный ритм, набор границ и способы проявлять близость. Важнее внешних стандартов взаимное согласие, безопасность, уважение и удовлетворённость обоих.', womenRating: 8, menRating: 7 },
];
